internal static class JobTrackCli
{
    public const string ApiUrlEnv = "JOBTRACK_API_URL";
    public const string ApiKeyEnv = "JOBTRACK_API_KEY";
    internal const int ExitUsage = 64;
    internal static string PackageVersion =>
        typeof(JobTrackCli).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
        ?? typeof(JobTrackCli).Assembly.GetName().Version?.ToString(3)
        ?? "unknown";

    internal static string Version => $"jt {PackageVersion}";

    internal static Task<int> RunAsync(IEnumerable<string> args, CancellationToken cancellationToken = default) =>
        CreateCommandApp().RunAsync(args, cancellationToken);

    internal static ICommandApp CreateCommandApp(
        IAnsiConsole? console = null,
        TextWriter? error = null,
        IJobTrackApi? api = null)
    {
        var runtime = new CommandRuntime(
            console ?? AnsiConsole.Console,
            error ?? Console.Error,
            api ?? CreateDefaultApiClient());
        var app = new CommandApp(new CommandTypeRegistrar(runtime));

        app.Configure(config =>
        {
            config.SetApplicationName("jt");
            config.SetApplicationVersion(Version);
            config.UseStrictParsing();
            config.SetExceptionHandler((ex, _) => HandleException(ex, runtime));

            config.ConfigureConsole(runtime.Console);

            config.AddBranch("task", task =>
            {
                task.SetDescription("Manage JobTrack tasks.");
                task.SetDefaultCommand<TaskMissingSubcommandCommand>();
                task.AddCommand<TaskListCommand>("list")
                    .WithDescription(DescriptionOf<TaskListCommand>())
                    .WithData(runtime);
                task.AddCommand<TaskShowCommand>("show")
                    .WithDescription(DescriptionOf<TaskShowCommand>())
                    .WithData(runtime);
                task.AddCommand<TaskCreateCommand>("create")
                    .WithDescription(DescriptionOf<TaskCreateCommand>())
                    .WithData(runtime);
                task.AddCommand<TaskUpdateCommand>("update")
                    .WithDescription(DescriptionOf<TaskUpdateCommand>())
                    .WithData(runtime);
            });

            config.AddCommand<WhoamiCommand>("whoami")
                .WithDescription(DescriptionOf<WhoamiCommand>())
                .WithData(runtime);
            config.AddCommand<VersionCommand>("version")
                .WithDescription(DescriptionOf<VersionCommand>())
                .WithData(runtime);
        });

        return app;
    }

    internal static IJobTrackApi CreateDefaultApiClient() =>
        new EnvJobTrackApiClient((baseUrl, key) => NewClient(baseUrl, key));

    internal static HttpClient NewClient(string baseUrl, string key, HttpMessageHandler? handler = null)
    {
        var http = handler is null
            ? new HttpClient()
            : new HttpClient(handler, disposeHandler: false);
        http.BaseAddress = ValidateApiBaseUrl(baseUrl);
        http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
        http.DefaultRequestHeaders.UserAgent.Add(new ProductInfoHeaderValue("jt", PackageVersion));
        return http;
    }

    private static Uri ValidateApiBaseUrl(string baseUrl)
    {
        if (!Uri.TryCreate(baseUrl, UriKind.Absolute, out var uri))
        {
            throw new InvalidOperationException($"{ApiUrlEnv} must be an absolute HTTP or HTTPS URL");
        }

        if (uri.Scheme == Uri.UriSchemeHttps)
        {
            return uri;
        }

        if (uri.Scheme == Uri.UriSchemeHttp)
        {
            if (IsLoopbackHost(uri))
            {
                return uri;
            }

            throw new InvalidOperationException(
                $"{ApiUrlEnv} must use HTTPS unless it points to localhost or a loopback address");
        }

        throw new InvalidOperationException($"{ApiUrlEnv} must be an HTTP or HTTPS URL");
    }

    private static bool IsLoopbackHost(Uri uri)
    {
        if (uri.IsLoopback)
        {
            return true;
        }

        if (IPAddress.TryParse(uri.Host, out var address))
        {
            return IPAddress.IsLoopback(address);
        }

        return string.Equals(uri.Host, "localhost", StringComparison.OrdinalIgnoreCase);
    }

    private static string DescriptionOf<T>() =>
        typeof(T).GetCustomAttribute<DescriptionAttribute>()?.Description ?? typeof(T).Name;

    private static int HandleException(Exception ex, CommandRuntime runtime)
    {
        if (ex is CommandAppException)
        {
            runtime.Error.WriteLine($"jt: {ex.Message}");
            return JobTrackCli.ExitUsage;
        }

        runtime.Error.WriteLine($"jt: {ex.Message}");
        return 1;
    }
}

internal sealed class CommandTypeRegistrar(CommandRuntime runtime) : ITypeRegistrar
{
    private readonly Dictionary<Type, Func<object>> _registrations = new();

    public ITypeResolver Build() => new CommandTypeResolver(runtime, _registrations);

    public void Register(Type service, Type implementation) =>
        _registrations[service] = () => CommandTypeResolver.CreateInstance(runtime, implementation);

    public void RegisterInstance(Type service, object implementation) =>
        _registrations[service] = () => implementation;

    public void RegisterLazy(Type service, Func<object> factory) =>
        _registrations[service] = factory;
}

internal sealed class CommandTypeResolver(
    CommandRuntime runtime,
    IReadOnlyDictionary<Type, Func<object>> registrations) : ITypeResolver
{
    public object? Resolve(Type? type)
    {
        if (type is null)
        {
            return null;
        }

        if (registrations.TryGetValue(type, out var factory))
        {
            return factory();
        }

        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(IEnumerable<>))
        {
            return Array.CreateInstance(type.GetGenericArguments()[0], 0);
        }

        return type == typeof(TaskMissingSubcommandCommand)
            ? CreateInstance(runtime, type)
            : null;
    }

    public static object CreateInstance(CommandRuntime runtime, Type type) =>
        type == typeof(TaskMissingSubcommandCommand)
            ? new TaskMissingSubcommandCommand(runtime)
            : Activator.CreateInstance(type)
                ?? throw new InvalidOperationException($"Could not create command type {type.FullName}.");
}

