    private static async Task<(CommandResult Result, RecordedRequest Request)> RunWithApiResponseAsync(
        string[] args,
        string responseBody,
        int statusCode = 200,
        string reasonPhrase = "OK",
        string apiUrl = "http://127.0.0.1")
    {
        using var handler = new RecordingHandler(responseBody, statusCode, reasonPhrase);
        using var env = new EnvironmentScope(apiUrl, "jt_test_key");
        var api = new EnvJobTrackApiClient((baseUrl, key) => JobTrackCli.NewClient(baseUrl, key, handler));
        var result = await RunAsync(args, api);

        return (result, handler.Request ?? throw new InvalidOperationException("No HTTP request was recorded."));
    }

    private static JsonElement AssertUntrustedJsonEnvelope(JsonDocument output)
    {
