   688	internal static class UrlBuilder
   689	{
   690	    public static string QueryString(params (string Name, string? Value)[] values)
   691	    {
   692	        var parts = new List<string>();
   693	        foreach (var (name, value) in values)
   694	        {
   695	            var normalizedValue = value?.Trim();
   696	            if (!string.IsNullOrWhiteSpace(normalizedValue))
   697	            {
   698	                parts.Add($"{Uri.EscapeDataString(name)}={Uri.EscapeDataString(normalizedValue)}");
   699	            }
   700	        }
   701	
   702	        return parts.Count == 0 ? string.Empty : "?" + string.Join("&", parts);
